python3 << 'EOF'
target='....((((((((....((..(...................)..(((...((....))...((....))........))).......))))))))))....'
import RNA
base='AAAGGGUUCAUUAAGGCCGAUUCUCUACUAAAACAUAACUACUCGCACAGCGCAGGCACCGGACACCCAGAUUAACGCGAUACACAGGAAUGAACCAAAU'
print('20',base[20],'40',base[40],'42',base[42],'79',base[79])
# 20=U,40=A (would-be WC pair, weak). 42=C,79=A spurious? C-A is mismatch not pair. Wait spurious means paired in MFE.
# Let me see the actual fold context
# Try: 20->G, 40->C (strengthen). 42-> break pair with 79.
best=None
for v20 in 'GCU':
    for v40 in 'ACG':
        pairs_ok={'A':'U','U':'A','G':'C','C':'G','G':'U','U':'G'}
        if v40!=pairs_ok.get(v20) and v40!=('U' if v20=='G' else ''):
            # allow only WC/wobble
            if (v20,v40) not in [('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')]:
                continue
        for v42 in 'ACGU':
            for v79 in 'ACGU':
                t=base
                t=t[:20]+v20+t[21:40]+v40+t[41:42]+v42+t[43:79]+v79+t[80:]
                fc=RNA.fold_compound(t)
                m,e=fc.mfe()
                d=RNA.bp_distance(m,target)
                if best is None or d<best[0]:
                    best=(d,e,t)
                if d==0:
                    print('SOLVED',t)
print('best',best[0],round(best[1],2))
print(best[2])
EOF

